package dev.hrutvik.billing.usage;
import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.time.Instant; import java.util.Map; import java.util.UUID; import static org.assertj.core.api.Assertions.assertThat;
class UsageFingerprintTest { @Test void normalizesQuantityAndAttributeOrder(){var f=new UsageFingerprint();var t=Instant.parse("2026-11-01T10:00:00Z");var subscription=UUID.randomUUID();var a=new UsageEventRequest("evt",subscription," API_CALLS ",new BigDecimal("10.00"),t,Map.of("region","in","model","pro"));var b=new UsageEventRequest("evt",subscription,"api_calls",new BigDecimal("10"),t,Map.of("model","pro","region","in"));assertThat(f.create(a)).isEqualTo(f.create(b));} @Test void subscriptionChangesFingerprint(){var f=new UsageFingerprint();var t=Instant.parse("2026-11-01T10:00:00Z");var a=new UsageEventRequest("evt",UUID.randomUUID(),"api_calls",BigDecimal.ONE,t,Map.of());var b=new UsageEventRequest("evt",UUID.randomUUID(),"api_calls",BigDecimal.ONE,t,Map.of());assertThat(f.create(a)).isNotEqualTo(f.create(b));} }
